export const UI_BLOCKS_GUIDANCE = "UI blocks: a fenced openui-lang block in your reply draws native UI there; keep the explanation in Markdown around it.\nUse one for data or structure the user would otherwise picture: values across items, comparisons, flows, trends, status. Not for a few numbers, a short list, code, or when asked for plain text. Several per reply are fine.\nPer-item decisions: a Card per item, a Button per option, value = the item. Choices collect until each decision has one (or the user sends early), then reach you together as your next turn. A question your current turn waits on goes through openchamber_render with ui (this language) and awaitAnswer.\n\nSyntax: one statement per line, name = Component(args); first line root = Stack([...]). Positional args in signature order, optional ones droppable from the end. Strings \"...\", arrays [...], objects {key: value}. Every name must be reachable from root.\nItem = any component below except Tab and Series. Card holds no Card or Tabs; Row holds no Row or Tabs; Tab holds no Tabs. Tone = \"neutral\" | \"info\" | \"success\" | \"warning\" | \"error\".\n\nExamples:\nroot = Stack([note, flow])\nnote = Callout(\"Routers rewrite the MAC header, keep the IP header.\", \"info\")\nflow = Steps([{title: \"Sender\", status: \"done\"}, {title: \"Router\", status: \"current\"}, {title: \"Receiver\"}], \"row\")\n\nroot = Stack([a])\na = Card(\"#12 Login on Safari\", [Badge(\"bug\", \"error\"), Text(\"Broken since 2.1 on macOS.\"), Button(\"Fix now\", \"primary\", \"#12 Login on Safari\"), Button(\"Later\", \"secondary\", \"#12 Login on Safari\")])\n\nComponents:\nStack(children: Item[]): the root\nRow(children: Item[]): side by side, wraps\nCard(title: string, children: Item[]): title \"\" for none\nTabs(tabs: Tab[])\nTab(label: string, children: Item[])\nText(markdown: string)\nBadge(label: string, tone?: Tone)\nCallout(markdown: string, tone?: Tone, title?: string)\nKeyValue(items: {label: string, value: string | number}[])\nTable(columns: string[], rows: (string | number)[][])\nStat(label: string, value: string | number, delta?: string, tone?: Tone): a key number; delta like \"+12%\"\nProgress(label: string, value: number, max?: number): max defaults to 100\nSteps(items: {title: string, markdown?: string, status?: \"done\" | \"current\" | \"todo\" | \"blocked\"}[], direction?: \"column\" | \"row\"): flow joined by arrows\nBarChart(labels: string[], series: Series[], unit?: string): categories\nLineChart(labels: string[], series: Series[], unit?: string): trend\nSeries(name: string, values: number[]): one value per label; null = no data\nChoice(name: string, options: string[], label?: string, multiple?: boolean): name keys the answer\nInput(name: string, label?: string, placeholder?: string, multiline?: boolean): name keys the answer\nButton(label: string, variant?: \"primary\" | \"secondary\", value?: string): value = the item it decides; primary = your pick, one per decision";
